{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or any(type(s) is not str for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    by_id = {}
    roots = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("missing node field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if type(node_id) is not str or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and type(parent) is not str:
            raise ValueError("parent must be null or a string")
        if type(symbol) is not str or type(depth) is not int or depth < 0:
            raise ValueError("invalid node identity or depth")
        if type(removable) is not bool:
            raise ValueError("removable must be boolean")
        if type(utility) not in (int, float):
            raise ValueError("utility must be numeric")
        try:
            if not math.isfinite(utility):
                raise ValueError("utility must be finite")
        except (OverflowError, TypeError):
            raise ValueError("utility must be finite")
        by_id[node_id] = node
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    children = {node_id: [] for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id or parent == node_id:
                raise ValueError("invalid parent reference")
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("invalid depth")
            children[parent].append(node_id)
        elif node["depth"] != 0:
            raise ValueError("root depth must be zero")

    visited = set()
    stack = [roots[0]]
    while stack:
        node_id = stack.pop()
        if node_id in visited:
            raise ValueError("cyclic tree")
        visited.add(node_id)
        stack.extend(children[node_id])
    if len(visited) != len(by_id):
        raise ValueError("tree is disconnected")

    required = set(required_symbols)
    if any(symbol not in {node["symbol"] for node in nodes} for symbol in required):
        raise ValueError("required symbol is absent")

    active = set(by_id)
    removed = []
    for node_id in sorted(by_id, key=lambda identifier: (-by_id[identifier]["depth"], identifier)):
        node = by_id[node_id]
        if node_id == roots[0] or not node["removable"] or node["symbol"] in required:
            continue
        if any(child in active for child in children[node_id]):
            continue
        remaining_symbols = {by_id[active_id]["symbol"] for active_id in active if active_id != node_id}
        if not required.issubset(remaining_symbols):
            continue
        active.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(active)
    }"}
